export function copyLCMSummary(i: LCMInput, r: LCMResult): string {
  return `
LCM Summary

Numbers: ${i.numbers.join(", ")}

LCM: ${r.lcm}
`.trim();
}

edits.replace:
export function copyLCMSummary(i: LCMInput, r: LCMResult, lang: "en" | "es" = "en"): string {
  if (lang === "es") {
    return `
Resumen de MCM

Números: ${i.numbers.join(", ")}

MCM: ${r.lcm}
`.trim();
  }
  return `
LCM Summary

Numbers: ${i.numbers.join(", ")}

LCM: ${r.lcm}
`.trim();
}
